CREATE TABLE public.booking_channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), name text NOT NULL, utm_source text NOT NULL CHECK(utm_source ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), utm_medium text NOT NULL CHECK(utm_medium ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), active boolean NOT NULL DEFAULT true, sort integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, UNIQUE(tenant_id,utm_source));
GRANT SELECT,INSERT,UPDATE ON public.booking_channels TO authenticated; GRANT ALL ON public.booking_channels TO service_role;
ALTER TABLE public.booking_channels ENABLE ROW LEVEL SECURITY;
CREATE POLICY channels_access ON public.booking_channels FOR ALL TO authenticated USING(tenant_id=public.current_tenant() AND public.is_aal2() AND public.has_permission('booking_links.manage')) WITH CHECK(tenant_id=public.current_tenant() AND public.is_aal2() AND public.has_permission('booking_links.manage'));
CREATE TABLE public.booking_places (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), channel_id uuid NOT NULL REFERENCES public.booking_channels(id), name text NOT NULL, code text NOT NULL CHECK(code ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), active boolean NOT NULL DEFAULT true, sort integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, UNIQUE(channel_id,code));
GRANT SELECT,INSERT,UPDATE ON public.booking_places TO authenticated; GRANT ALL ON public.booking_places TO service_role;
ALTER TABLE public.booking_places ENABLE ROW LEVEL SECURITY;
CREATE POLICY places_access ON public.booking_places FOR ALL TO authenticated USING(tenant_id=public.current_tenant() AND public.is_aal2() AND public.has_permission('booking_links.manage')) WITH CHECK(tenant_id=public.current_tenant() AND public.is_aal2() AND public.has_permission('booking_links.manage'));
CREATE TABLE public.booking_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), name text NOT NULL, code text NOT NULL CHECK(code ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), starts_on date, ends_on date, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, UNIQUE(tenant_id,code), CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on));
GRANT SELECT,INSERT,UPDATE ON public.booking_campaigns TO authenticated; GRANT ALL ON public.booking_campaigns TO service_role;
ALTER TABLE public.booking_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaigns_access ON public.booking_campaigns FOR ALL TO authenticated USING(tenant_id=public.current_tenant() AND public.is_aal2() AND public.has_permission('booking_links.manage')) WITH CHECK(tenant_id=public.current_tenant() AND public.is_aal2() AND public.has_permission('booking_links.manage'));
ALTER TABLE public.booking_links ADD COLUMN hash text NOT NULL DEFAULT substr(replace(gen_random_uuid()::text,'-',''),1,6), ADD COLUMN channel_id uuid REFERENCES public.booking_channels(id), ADD COLUMN place_id uuid REFERENCES public.booking_places(id), ADD COLUMN campaign_id uuid REFERENCES public.booking_campaigns(id), ADD COLUMN extra text NOT NULL DEFAULT '';
ALTER TABLE public.booking_links ADD CONSTRAINT booking_hash_format CHECK(hash ~ '^[a-z0-9]{6}$'), ADD CONSTRAINT booking_hash_unique UNIQUE(tenant_id,hash);
ALTER TABLE public.appointments ADD COLUMN booking_channel_id uuid REFERENCES public.booking_channels(id), ADD COLUMN booking_place_id uuid REFERENCES public.booking_places(id), ADD COLUMN booking_campaign_id uuid REFERENCES public.booking_campaigns(id), ADD COLUMN booking_hash text, ADD COLUMN booking_extra text, ADD COLUMN booking_attribution jsonb;
CREATE FUNCTION public.guard_booking_codes() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_TABLE_NAME='booking_channels' AND (NEW.utm_source<>OLD.utm_source OR NEW.utm_medium<>OLD.utm_medium) AND EXISTS(SELECT 1 FROM public.booking_links WHERE channel_id=OLD.id) THEN RAISE EXCEPTION 'Een code die in gebruik is kun je niet wijzigen'; END IF;
 IF TG_TABLE_NAME='booking_places' AND (NEW.code<>OLD.code OR NEW.channel_id<>OLD.channel_id) AND EXISTS(SELECT 1 FROM public.booking_links WHERE place_id=OLD.id) THEN RAISE EXCEPTION 'Een code die in gebruik is kun je niet wijzigen'; END IF;
 IF TG_TABLE_NAME='booking_campaigns' AND (NEW.code<>OLD.code) AND (OLD.code='doorlopend' OR EXISTS(SELECT 1 FROM public.booking_links WHERE campaign_id=OLD.id)) THEN RAISE EXCEPTION 'Een code die in gebruik is kun je niet wijzigen'; END IF;
 IF TG_TABLE_NAME='booking_campaigns' AND OLD.code='doorlopend' AND NOT NEW.active THEN RAISE EXCEPTION 'Geen campagne blijft beschikbaar'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER channels_codes BEFORE UPDATE ON public.booking_channels FOR EACH ROW EXECUTE FUNCTION public.guard_booking_codes();
CREATE TRIGGER places_codes BEFORE UPDATE ON public.booking_places FOR EACH ROW EXECUTE FUNCTION public.guard_booking_codes();
CREATE TRIGGER campaigns_codes BEFORE UPDATE ON public.booking_campaigns FOR EACH ROW EXECUTE FUNCTION public.guard_booking_codes();
CREATE TRIGGER channels_touch BEFORE UPDATE ON public.booking_channels FOR EACH ROW EXECUTE FUNCTION public.touch_updated();
CREATE TRIGGER places_touch BEFORE UPDATE ON public.booking_places FOR EACH ROW EXECUTE FUNCTION public.touch_updated();
CREATE TRIGGER campaigns_touch BEFORE UPDATE ON public.booking_campaigns FOR EACH ROW EXECUTE FUNCTION public.touch_updated();
CREATE TRIGGER channels_audit AFTER INSERT OR UPDATE ON public.booking_channels FOR EACH ROW EXECUTE FUNCTION public.audit_row_change();
CREATE TRIGGER places_audit AFTER INSERT OR UPDATE ON public.booking_places FOR EACH ROW EXECUTE FUNCTION public.audit_row_change();
CREATE TRIGGER campaigns_audit AFTER INSERT OR UPDATE ON public.booking_campaigns FOR EACH ROW EXECUTE FUNCTION public.audit_row_change();